package com.example.bandlink.service; import com.example.bandlink.entity.*; import com.example.bandlink.repository.UserRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminUserService {private final UserRepository users;public AdminUserService(UserRepository u){users=u;}@Transactional public void suspend(Long id){change(id,UserStatus.SUSPENDED);}@Transactional public void unsuspend(Long id){change(id,UserStatus.ACTIVE);}private void change(Long id,UserStatus s){User u=users.findById(id).orElseThrow();if(u.getStatus()!=UserStatus.WITHDRAWN)u.setStatus(s);}}
